CREATE OR REPLACE FUNCTION public.mha_create_company_inventory_sku(p_store_id bigint, p_sku_code text, p_sku_name text, p_category text, p_order_uom text, p_inventory_uom text, p_recipe_uom text, p_order_to_inventory numeric, p_inventory_to_recipe numeric)\n RETURNS bigint\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_company bigint;v_id bigint;\nbegin\n select company_id into v_company from public.mha_current_store_context(p_store_id);\n if not public.mha_has_permission(v_company,'inventory','EDIT') then raise exception 'Inventory edit permission denied' using errcode='42501';end if;\n if length(trim(coalesce(p_sku_code,''))) not between 1 and 60 or length(trim(coalesce(p_sku_name,''))) not between 1 and 200 then raise exception 'Invalid SKU code or name';end if;\n if length(trim(coalesce(p_inventory_uom,''))) not between 1 and 30 or length(trim(coalesce(p_recipe_uom,''))) not between 1 and 30 or length(trim(coalesce(p_order_uom,''))) not between 1 and 30 then raise exception 'All units are required';end if;\n if p_order_to_inventory is null or p_order_to_inventory<=0 or p_inventory_to_recipe is null or p_inventory_to_recipe<=0 then raise exception 'Conversion factors must be positive';end if;\n perform pg_advisory_xact_lock(v_company,99101);\n if exists(select 1 from public.inventory_sku where company_id=v_company and lower(sku_code)=lower(trim(p_sku_code))) then raise exception 'SKU code already exists in this company';end if;\n insert into public.inventory_sku(company_id,sku_code,sku_name,category,order_uom,inventory_uom,recipe_uom,order_to_inventory,inventory_to_recipe,current_stock,minimum_stock,low_stock_level)\n values(v_company,trim(p_sku_code),trim(p_sku_name),nullif(trim(coalesce(p_category,'')),''),trim(p_order_uom),trim(p_inventory_uom),trim(p_recipe_uom),p_order_to_inventory,p_inventory_to_recipe,0,0,0) returning id into v_id;\n return v_id;\nend $function$\n